const FALLBACK: Record<TextStyleKey, number> = {
  sans800: 0.62,
  sans700: 0.6,
  sans500: 0.55,
  mono400: 0.6,
};

/** Pixel width of `text` at `size` px in the given brand style. */
export function measure(text: string, style: TextStyleKey, size: number): number {
  const row = W[text];
  const em = row ? row[style] : text.split('').reduce((acc, ch) => acc + (W[ch]?.[style] ?? FALLBACK[style]), 0);
  return em * size;
}

/** Em advance, for letter-spacing-aware composition. */
export function measureEm(text: string, style: TextStyleKey): number {
  const row = W[text];
  if (row) return row[style];
  return text.split('').reduce((acc, ch) => acc + (W[ch]?.[style] ?? FALLBACK[style]), 0);
}

/** Advance width including SVG letter-spacing (applied after every glyph). */
export function measureTracked(text: string, style: TextStyleKey, size: number, trackingEm: number): number {
  return measure(text, style, size) + trackingEm * size * text.length;
}

export const MEASURED_STRINGS = Object.keys(W);
